UNION ALL SELECT 'B' AS opt_label, 'who' AS opt_text, 0 AS opt_correct
UNION ALL SELECT 'C' AS opt_label, 'which' AS opt_text, 0 AS opt_correct
UNION ALL SELECT 'D' AS opt_label, 'where' AS opt_text, 1 AS opt_correct
