INSERT INTO practice_questions(practice_set_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:1]%' ORDER BY id LIMIT 1),'Ms. Lan is a very _____ employee who always meets deadlines.','{"translation": "Cô Lan là một nhân viên rất đáng tin cậy, luôn hoàn thành đúng hạn.", "options_vi": {"A": "sự đáng tin cậy", "B": "dựa vào", "C": "một cách đáng tin cậy", "D": "đáng tin cậy"}, "explanation": "Giữa very và danh từ employee cần tính từ reliable. Reliability là danh từ, rely là động từ, còn reliably là trạng từ nên không bổ nghĩa trực tiếp cho employee.", "words": ["employee", "deadlines"]}',2 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:1]%' ORDER BY id LIMIT 1) AND question_text='Ms. Lan is a very _____ employee who always meets deadlines.');
