INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l2%' ORDER BY id LIMIT 1),'When does résumé feedback become available?','{"translation": "Khi nào bắt đầu có góp ý CV?", "options_vi": {"A": "10 giờ sáng", "B": "Buổi trưa", "C": "3 giờ chiều", "D": "Ngày 18 tháng 10"}, "evidence": "A résumé review desk will be available from noon.", "explanation": "From noon nghĩa là bắt đầu từ trưa. 10 giờ là giờ mở hội chợ, 3 giờ là giờ kết thúc, ngày 18 là hạn đăng ký.", "analysis": {"A": "Không phù hợp với dẫn chứng: 10 giờ sáng. From noon nghĩa là bắt đầu từ trưa. 10 giờ là giờ mở hội chợ, 3 giờ là giờ kết thúc, ngày 18 là hạn đăng ký.", "B": "Đúng. From noon nghĩa là bắt đầu từ trưa. 10 giờ là giờ mở hội chợ, 3 giờ là giờ kết thúc, ngày 18 là hạn đăng ký.", "C": "Không phù hợp với dẫn chứng: 3 giờ chiều. From noon nghĩa là bắt đầu từ trưa. 10 giờ là giờ mở hội chợ, 3 giờ là giờ kết thúc, ngày 18 là hạn đăng ký.", "D": "Không phù hợp với dẫn chứng: Ngày 18 tháng 10. From noon nghĩa là bắt đầu từ trưa. 10 giờ là giờ mở hội chợ, 3 giờ là giờ kết thúc, ngày 18 là hạn đăng ký."}}',161 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT 1) AND question_text='When does résumé feedback become available?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:2]%' ORDER BY id LIMIT