INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l4%' ORDER BY id LIMIT 1),'Which item is not included in the monthly plan price?','{"translation": "Khoản nào không gồm trong giá gói hàng tháng?", "options_vi": {"A": "Hai lần đến mỗi quý", "B": "Hỗ trợ ngày thường", "C": "Linh kiện thay thế", "D": "Lần kỹ thuật viên đến đầu tiên"}, "evidence": "Replacement parts are billed separately.", "explanation": "Linh kiện được tính riêng, còn hỗ trợ ngày thường và hai lần đến mỗi quý thuộc gói.", "analysis": {"A": "Không phù hợp với dẫn chứng: Hai lần đến mỗi quý. Linh kiện được tính riêng, còn hỗ trợ ngày thường và hai lần đến mỗi quý thuộc gói.", "B": "Không phù hợp với dẫn chứng: Hỗ trợ ngày thường. Linh kiện được tính riêng, còn hỗ trợ ngày thường và hai lần đến mỗi quý thuộc gói.", "C": "Đúng. Linh kiện được tính riêng, còn hỗ trợ ngày thường và hai lần đến mỗi quý thuộc gói.", "D": "Không phù hợp với dẫn chứng: Lần kỹ thuật viên đến đầu tiên. Linh kiện được tính riêng, còn hỗ trợ ngày thường và hai lần đến mỗi quý thuộc gói."}}',161 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND question_text='Which item is not included in the monthly plan price?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n1