INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND passage_text LIKE '%n11-reading-expansion-20261116-p7-l4%' ORDER BY id LIMIT 1),'What can be inferred about the March request?','{"translation": "Có thể suy ra gì về yêu cầu tháng 3?", "options_vi": {"A": "Lần đầu trong quý", "B": "Liên quan sự cố tái diễn", "C": "Yêu cầu hủy gói", "D": "Yêu cầu hỗ trợ cuối tuần"}, "evidence": "It has stopped printing again.", "explanation": "Again cho thấy máy lại ngừng in sau các lần bảo dưỡng; không có yêu cầu hủy gói hoặc chỉ định cuối tuần.", "analysis": {"A": "Không phù hợp với dẫn chứng: Lần đầu trong quý. Again cho thấy máy lại ngừng in sau các lần bảo dưỡng; không có yêu cầu hủy gói hoặc chỉ định cuối tuần.", "B": "Đúng. Again cho thấy máy lại ngừng in sau các lần bảo dưỡng; không có yêu cầu hủy gói hoặc chỉ định cuối tuần.", "C": "Không phù hợp với dẫn chứng: Yêu cầu hủy gói. Again cho thấy máy lại ngừng in sau các lần bảo dưỡng; không có yêu cầu hủy gói hoặc chỉ định cuối tuần.", "D": "Không phù hợp với dẫn chứng: Yêu cầu hỗ trợ cuối tuần. Again cho thấy máy lại ngừng in sau các lần bảo dưỡng; không có yêu cầu hủy gói hoặc chỉ định cuối tuần."}}',162 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:4]%' ORDER BY id LIMIT 1) AND question_text='What can be inferred about the March request?' AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVE